//angular = require 'angular'

const module = angular.module("irtech.netcity.school.users",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components",
		"irtech.netcity.directive"
	]);

require("./common/userListCtrl.js");
require("./students/studentListCtrl.js");
require("./parents/parentListCtrl.js");
require("./staff/staffListCtrl.js");

import { StaffImportCtrl } from "approot/school/users/staff/staffImportCtrl.js";
import { UsersRepository } from "approot/school/users/repository.js";

require("approot/global/directives/storageDirective.coffee");

module
	.factory("usersRepository", ($http, $dialogs, $alerts, $q) => new UsersRepository($http, $dialogs, $alerts, $q))
	.controller("StaffImportCtrl", StaffImportCtrl)
	.config(($routeProvider, $locationProvider) => {
		const registryTemplate = "/static/dist/app/global/templates/registry.html";

		$routeProvider
			.when("/students/", {
				templateUrl: registryTemplate,
				controller: "StudentListCtrl"
			})
			.when("/parents/", {
				templateUrl: registryTemplate,
				controller: "ParentListCtrl"
			})
			.when("/staff/", {
				templateUrl: registryTemplate,
				controller: "StaffListCtrl"
			})
			.when("/staffImport/", {
				templateUrl: "/static/dist/app/school/users/staff/staffImportTemplate.html",
				controller: "StaffImportCtrl as ctrl"
			});

		$locationProvider.hashPrefix('');

		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



