"use strict";

import * as Rights from "approot/global/references/rights.js";
import * as FuncTypes from "approot/global/references/funcTypes.js";
import * as TabItems from "approot/global/references/tabItems.js";

angular
	.module("irtech.netcity.school.users")
	.controller("ParentListCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider, pageContext, navigationService) => {

		pageContext.title = language.Generic.FilterUsers.kParentList;
		pageContext.parent = null;
		pageContext.tabItem = TabItems.tbParents;

		let hasRightsToGenerateNewPasswords = appContext.hasRights([Rights.arUsersEditStudents, Rights.arUsersEditAccountStudentsParents]);
		$scope.canGenerateNewPass = appContext.funcType != FuncTypes.addSchool && hasRightsToGenerateNewPasswords;

		$scope.isLimitAccess = appContext.hasAnyRight([Rights.arShortInfoStudents]);

		$scope.editUser = (user) => {
			navigationService.navigateTo("/angular/school/userinfo/parents/" + user.id);
		};

		const addBtn = {
			title: language.Generic.Buttons.kAdd,
			icon: "glyphicon glyphicon-plus-sign",
			action: () => {
				postTo({ path: "/asp/SetupSchool/ParentQAdd.asp" });
			}
		};

		$scope.registry = {
			url: "/webapi/users/parents/registry",
			filtersUrl: "/webapi/users/parents/registry/filter",
			fieldDecorators: {
				"nickname": { type: "link", action: $scope.editUser }
			},
			buttons: []
		};

		if (!appContext.readOnly) {
			if (appContext.hasAnyRight([Rights.arUsersEditStudents])) {
				$scope.registry.buttons.push(addBtn);
			}
		}

		settingsProvider.AppFlags.PersonData().then((personData) => {
			if (!personData) {
				$scope.registry.fieldDecorators["nickname"] = null;
				addBtn.hide = true;
				$scope.btnExport.hide = true;
			}
		});

		$controller("UserListCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider });

	});


