"use strict"

import { filterPanel } from "webroot/vendor/pages/js/filters.coffee";

class StaffImportCtrl {
	constructor(pageContext, $appLoader, $q, $alerts, $location, usersRepository, appContext) {

		this.isAllSelected = false;
		this.appLoader = $appLoader;
		this.repository = usersRepository;
		this.$location = $location;
		this.pageContext = pageContext;
		this.alerts = $alerts;
		this.appContext = appContext;

		pageContext.title = language.Generic.Import.kStaffImport;

		pageContext.parent = {
			title: language.Generic.FilterUsers.kStaffList,
			href: `/staff/`,
		}

		this.filterPanel = null;
		this.loadFilterPanel();
	}

	loadFilterPanel() {
		this.repository.getFilterPanelForImportStaff().then((response) => {

			const fp = response.data;
			const fpInfo = fp.filterPanel;
			const fpSources = fp.filterSources;

			const fpElem = $("#filters");

			let fpUrl = "/webapi/users/staff/import/filterpanel";

			this.filterPanel = new filterPanel(fpElem, fpInfo, fpSources, fpUrl);
			this.filterPanel.ready((fpValues) => {
				this.load();
			})

			this.load();

		}).catch((error) => {
			console.error(error);
		})
	}


	doImport() {

		let usersIds = $('input[name="StaffID"]:checked')
			.map(function () { return this.value }).get();

		if (usersIds < 1) {
			alert(language.Generic.ServAdmin.kMustSelectStaff);
			return false;
		}

		setDBBusy();

		this.repository.postReuseUsers(usersIds, this.appContext.yearId)
			.then((data) => {
				this.$location.path("/staff/");
			})
			.then(() => {
				this.alerts.success("Импорт выполнен успешно");
			})
			.catch((err) => {
				console.error(err);
				this.alerts.error(err);
			});
	}

	load() {

		let fpValues = this.filterPanel.getValues();

		this.repository.getStaffsForImport(fpValues.schoolFilter)
			.then((response) => {
				this.staffs = response.data;
			});


		this.appLoader.hide();
	}





}

StaffImportCtrl.$inject = ["pageContext", "$appLoader", "$q", "$alerts", "$location", "usersRepository", "appContext"];
module.exports = { StaffImportCtrl }; 


