"use strict";

import * as FuncTypes from "approot/global/references/funcTypes.js";
import * as Roles from "approot/global/references/roles.js";

import passGenerate from "./generateNewPassword.js";

require("approot/global/controllers/registryCtrl.js");

angular
	.module("irtech.netcity.school.users")
	.controller("UserListCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider) => {

		deferredResLoader.loadJsScript("/vendor/pages/js/import.js");
		deferredResLoader.loadJsScript("/js/cryptoRSA/BigInt.js");
		deferredResLoader.loadJsScript("/js/cryptoRSA/Barrett.js");
		deferredResLoader.loadJsScript("/js/cryptoRSA/RSA.js");
		deferredResLoader.loadJsScript("/js/cryptoRSA/RSAHelper.js");
		deferredResLoader.loadJsScript("/js/ImportUpdatePersons.js");


		$scope.generatePass = {
			opened: false,
			begin: () => {
				$scope.selection.dropSelect();
				$scope.state.selectable = true;
				$scope.generatePass.opened = true;
				$scope.state.withMultiSelection = true;
			},
			cancel: () => {
				$scope.state.selectable = false;
				$scope.generatePass.opened = false;
				$scope.state.withMultiSelection = false;
			},
			go: () => {
				const userIds = _.pluck($scope.selection.selected, "id");
				passGenerate(userIds).then(() => {
					$scope.selection.dropSelect();
					$scope.state.withMultiSelection = false;
					$scope.generatePass.cancel();
					$scope.$apply();
				});
			},
			selectAll: () => {
				//если есть несколько страниц
				if ($scope.paging.totalRows > $scope.data.registryData.rows.length) {
					alert(language.Generic.Common.kWarnSelectAllUsers);
				}
				$scope.selection.dropSelect();
				$scope.selection.items = $scope.selection.items.concat($scope.data.registryData.rows);
			}
		}

		let isAdmin = appContext.roles.some((r) => r === Roles.admin || r === Roles.emAdmin);
		let showCreateNewPasswords = isAdmin && !appContext.readOnly && $scope.canGenerateNewPass;

		if (showCreateNewPasswords) {
			$scope.registry.extensions = {
				postButtonsTpl: "/static/dist/app/school/users/common/userExtraPostButtons.html"
			};

			const generatePassBtn = {
				title: language.Generic.Common.kCreateNewPasswords,
				action: $scope.generatePass.begin
			};

			$scope.registry.buttons.push(generatePassBtn);

			settingsProvider.AppFlags.PersonData().then((data) => {
				if (!data) {
					generatePassBtn.hide = true;
				}
			});
		}

		settingsProvider.AppFlags.PersonData().then((personData) => {
			$scope.showPersonEditWarn = !personData;

			if (!personData) {
				$scope.registry.extensions = {
					postButtonsTpl: "/static/dist/app/school/users/common/userExtraPostButtons.html"
				};
			}
		});

		$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });
	});


