"use strict";

import { filterPanel, dependencyTracker } from "webroot/vendor/pages/js/filters.coffee";
import MultiSelectable from "approot/global/multiSelectable.js";

angular
	.module("irtech.netcity.common")
	.controller("RegistryCommonCtrl", ($scope, $http, $document, $location, $appLoader, $dialogs, $uibModal, $alerts) => {

		//Описание настоек
		const defRegistryInfo = {
			//url реестра
			url: null,
			//url инициализации фильтр-панели
			filterUrl: null,
			//переопределения отображения полей
			fieldDecorators: null,
			//расширения внешнего вида
			extensions: {
				//шаблон контента между кнопок и таблицы
				postButtonsTpl: null
			},
			compactFilters: true
		};

		const initialPageSize = 50;

		$.extend($scope, {
			language: language,
			registry: $.extend({}, defRegistryInfo, $scope.registry),
			state: {
				dataReady: false,
				loading: false,
				emptyData: false,
				selectable: false,
				exporting: false,
				initing: true
			},
			filterInfo: {
				filterPanel: null
			},
			selection: new MultiSelectable(),
			data: {
				error: null,
				registry: null,
				registryData: null,
				search: {
					fieldId: null,
					fieldTitle: null,
					text: "",
					fields: []
				},
				fields: null,
				displayFields: null
			},
			paging: {
				//page: 1,
				//pageSize: 50,
				totalRows: 0
			}
		});

		$scope.$watch('paging.currentPageSize', function(newVal, oldVal) {
			if(newVal && (newVal < 1 || newVal > 999 || /[^0-9]/.test(newVal))) {
				$scope.paging.currentPageSize = oldVal;
			}
		});

		let scrollable = false;
		const body = $("body");

		const setLoadingState = () => {
			scrollable = document.body.scrollHeight > document.documentElement.clientHeight;

			$scope.state.dataReady = false;
			$scope.state.loading = true;
			$scope.selection.dropSelect();

			if (scrollable) {
				body.css({ "padding-right": "17px" });
			}
		}

		const unsetLoadingState = () => {
			if (scrollable) {
				body.css({ "padding-right": "" });
			}

			$scope.state.dataReady = true;
			$scope.state.loading = false;
		}

		$scope.clickRow = (event, row) => {
			let clickOnTag = event.target && event.target.tagName;
			if (clickOnTag === "A") {
				//исключаем нажатие на линках
				return;
			}

			if (!$scope.state.withMultiSelection) {
				//эмулирование единственности выбора
				if (!$scope.selection.isSelected(row)) {
					$scope.selection.dropSelect();
				}
			}
			$scope.selection.select(row);
		}

		//инициализация запрашиваемых полей
		const initRequestField = () => {
			const filterValues = $scope.filterInfo.filterPanel.getValues();

			const chain = _.chain($scope.data.fields)
				.filter((field) => {
					if (!field.dependencies) {
						return true;
					}
					return new dependencyTracker(field.dependencies).isSatisfied(filterValues);
				})
				.pluck("id");

			return chain.value();
		}

		const initAvailableFields = () => {
			const filterValues = $scope.filterInfo.filterPanel.getValues();

			const chain = _.chain($scope.data.registry.fields)
				.filter((field) => {
					if (!field.dependencies) {
						return true;
					}
					return new dependencyTracker(field.dependencies).isSatisfied(filterValues);
				});

			return chain.value();
		}

		const initDisplayFilters = () => {
			//инициализация полей реестра
			let chain = _.chain(initAvailableFields());

			if ($scope.data.registryData) {
				chain = chain.filter((f) => $scope.data.registryData.fields.indexOf(f.id) > -1);
			}
			if ($scope.registry.fieldDecorators) {
				chain = chain.each((f) => f.decorator = $scope.registry.fieldDecorators[f.id]);
			}
			$scope.data.displayFields = chain.sortBy((f) => f.order).value();
		}

		//инициализация кнопок и действий и их правил показа
		$scope.initCommandButtons = () => {
			const commands = $scope.data.registry.commands;
			const buttons = $scope.registry.buttons;

			const checkSelectionMode = (mode, defaultVal) => {
				if (mode === "Empty") {
					return $scope.selection.selected.length === 0;
				}
				else if (mode === "Single") {
					return $scope.selection.selected.length === 1;
				} else if (mode === "Multiple") {
					return $scope.selection.selected.length > 0;
				}
				return defaultVal;
			}
			
			$scope.state.withMultiSelection = false;
			if (commands && commands.length) {
				//если есть команды - то возможность выбора есть
				$scope.state.selectable = true;
				$scope.state.withMultiSelection = _.findWhere(commands, { mode: "Multiple" });
				_.each(commands, (cmd) => {cmd.isEnabled = () => { return checkSelectionMode(cmd.mode, false); }});
			}

			if (buttons && buttons.length) {
				$scope.state.selectable = $scope.state.selectable || _.some(buttons, (b) => b.selectionMode);
				$scope.state.withMultiSelection = $scope.state.withMultiSelection || _.findWhere(buttons, { selectionMode: "Multiple" });
				_.each(buttons, (btn) => { btn.isEnabled = () => { return checkSelectionMode(btn.selectionMode, true); }});
			}
		}

		$scope.state.initing = true;
		$http.get($scope.registry.url)
		.catch((response) => {
			$appLoader.hide();
			$scope.data.error = (response.data && response.data.message) || "Ошибка загрузки реестра";
		})
		.then((response) => {
			const registry = response.data;
			$scope.data.registry = registry;

			const fpInfo = registry.filterPanel.filterPanel;
			const fpSources = registry.filterPanel.filterSources;
			const fltPanel = $(".filters-panel").eq(0);

			$scope.initCommandButtons();

			//первичная инициализация полей реестра
			$scope.data.fields = _.filter(registry.fields, (f) => f.default);
			const fpUrl = $scope.registry.filtersUrl;
			$appLoader.hide();

			const fp = new filterPanel(fltPanel, fpInfo, fpSources, fpUrl);
			
			$scope.filterInfo.filterPanel = fp;
			$scope.filterInfo.filterPanel.ready(() => {
				$scope.state.initing = false;
				$scope.setSearchFields();
				$scope.$applyAsync();
			});
			$scope.setSearchFields();
			$scope.$emit("FilterPanelInitialized", fp);

			$scope.loadingState();
		});

		$scope.inputSearch = () => {
			$scope.load();
		}

		$scope.loadingState = () => {
			$http.get($scope.registry.url + "/state")
				.then((response) => {
					let registryState = {
						paging: {
							page: 1,
							pageSize: initialPageSize,
							currentPageSize: initialPageSize
						}
					}
					let needLoad = $scope.data.registry.autoLoad;
					if (!response || !response.data) {
						$scope.paging = angular.extend($scope.paging, registryState.paging);
					} else {
						needLoad = true;
						registryState = response.data;
						$scope.paging = angular.extend($scope.paging, registryState.paging);
						if (!$scope.paging.pageSize) {
							$scope.paging.pageSize = initialPageSize;
						}
						$scope.paging.currentPageSize = $scope.paging.pageSize;
						if (registryState.fields) {
							$scope.data.fields = _.filter($scope.data.registry.fields, (item) => _.find(registryState.fields, (stateField) => stateField === item.id));
						}
						if (registryState.search && registryState.search.text) {
							let stateSearchField = _.findWhere($scope.data.registry.fields, { id: registryState.search.fieldId });
							$scope.data.search.fieldTitle = stateSearchField.title;
							$scope.data.search.fieldId = stateSearchField.id;
							$scope.data.search.text = decodeURIComponent(registryState.search.text);
						}
						if (registryState.order && registryState.order.fieldId) {
							initDisplayFilters();

							let stateOrderField = _.findWhere($scope.data.registry.fields, { id: registryState.order.fieldId });
							_.each($scope.data.displayFields, (f) => f.sortOrder = null);
							stateOrderField.sortOrder = registryState.order.ascending ? "asc" : "desc";
						}
					}
					if (needLoad) {
						$scope.load();
					}
					$scope.state.initing = false;
					$appLoader.hide();
				},
				() => {
					$scope.state.initing = false;
					$appLoader.hide();
					$scope.data.error = "Ошибка загрузки реестра";
				});
		}

		$scope.inputSearch = _.debounce($scope.inputSearch, 800);

		$scope.setSearchField = (field) => {
			if ($scope.data.search && $scope.data.search.fieldId && $scope.data.search.fieldId === field.id && $scope.data.search.fieldTitle === field.title) {
				return;
			}
			$scope.data.search.text = "";
			$scope.data.search.fieldTitle = field.title;
			$scope.data.search.fieldId = field.id;
		}

		const searchNotByLastname = () => {
			const lastNameId = "lastName";

			let searchFilter = $scope.data.search;

			return searchFilter.text && searchFilter.fieldId !== lastNameId;
		}

		$scope.canExport = () => {
			const exportWarn = "Экспорт возможен только в случае заполненного фильтра \"Фамилия\"";

			if (searchNotByLastname()) {
				alert(exportWarn);
				return false;
			}

			return true;
		}

		$scope.equalArrays = (array1, array2) => {
			if (!array1 || !array2) {
				return false;
			}
			return !_.chain(array1)
				.difference(array2)
				.union(_.difference(array2, array1))
				.value()
				.length;
		}

		$scope.setSearchFields = () => {
			let availableFields = initAvailableFields();
			let availableFieldsArr = _.toArray(_.pluck(availableFields, "id"));
			$scope.data.search.fields = _.chain($scope.data.registry.fields)
				.filter((f) => f.search)
				.filter((item) => _.find(availableFieldsArr, (availableField) => availableField === item.id))
				.value();

			if ($scope.data.search.fields.length) {
				let searchField = _.find($scope.data.search.fields, (f) => f.default);
				searchField = _.find($scope.data.search.fields, (f) => f.searchByDefault) || searchField;
				if ($scope.data.search && $scope.data.search.fieldId && _.some($scope.data.search.fields, (fld) => fld.id === $scope.data.search.fieldId) && $scope.data.search.fieldId !== searchField.id) {
					return;
				}
				$scope.setSearchField(searchField);
			}
		}

		$scope.setSearch = (field) => {
			let text = "";
			if ($scope.data.search && $scope.data.search.fieldId === field.id) {
				text = $scope.data.search.text;
			}

			var modalInstance = $uibModal.open({
				template: `<div class="bootstrap-dialog type-primary">
								<div class="modal-header">
									<div class="bootstrap-dialog-title">
										<h4 class="modal-title">Поиск по полю \"{{field.title}}\"</h4> 
									</div>		
								</div>
							<div class="modal-body">
								<input class="form-control" type="text" ng-model="search">
							</div>

							<div class="modal-footer">
								<button class="btn btn-primary ng-binding" ng-click="set()">OK</button>
							</div>
						</div>`,
				controller: 'SetRegistryFieldSearchCtrl',
				title: 'Поиск по полю',
				resolve: {
					search: () => text,
					field: () => field
				}
			});

			modalInstance.result.then((search) => {
				if (search) {
					$scope.data.search = $.extend($scope.data.search, {
						fieldId: field.id,
						fieldTitle: field.title,
						text: search
					});
				} else {
					$scope.data.search.text = "";
				}
				$scope.load();
			});
		}

		$scope.clearSearch = () => {
			$scope.data.search.text = "";
			$scope.load();
		}

		$scope.setSortOrder = (field, newOrder) => {
			if (!newOrder) {
				if (!field.sortOrder) {
					newOrder = "asc";
				} else {
					newOrder = field.sortOrder === "asc" ? "desc" : "asc";
				}
			}
			_.each($scope.data.displayFields, (f) => f.sortOrder = null);
			field.sortOrder = angular.copy(newOrder);
			$scope.load();
		}

		$scope.pageChange = () => {
			if ($scope.state.loading) {
				return;
			}
			$scope.load();
		}

		const errorHandle = (message) => {
			$scope.data.error = message;
			$scope.state.dataReady = true;
			$scope.state.loading = false;
		}

		//загрузка данных
		$scope.load = () => {
			if (!$scope.filterInfo.filterPanel.validate()) {
				return;
			}
			setLoadingState();

			if (!$scope.paging.currentPageSize) {
				$scope.paging.currentPageSize = initialPageSize;
			}

			let data = {
				filterContext: {
					selectedData: $scope.filterInfo.filterPanel.getCtxValues()
				},
				fields: initRequestField(),
				page: $scope.paging.page,
				pageSize: $scope.paging.currentPageSize
			};

			if ($scope.data.search.fieldId && $scope.data.search.text) {
				data.search = {
					fieldId: $scope.data.search.fieldId,
					text: $scope.data.search.text
				};
			}

			let orderField = _.find($scope.data.displayFields, (f) => f.sortOrder);
			if (orderField) {
				data.order = {
					fieldId: orderField.id,
					ascending: orderField.sortOrder === "asc"
				}
			}

			$http.post($scope.registry.url, data)
				.then((response) => {
					$scope.data.error = null;

					try {

						$scope.data.registryData = response.data;
						$scope.paging.pageSize = $scope.paging.currentPageSize;
						//инициализация пейджинга
						if ($scope.paging.page !== $scope.data.registryData.page) {
							$scope.paging.page = $scope.data.registryData.page;
						}
						$scope.paging.totalRows = $scope.data.registryData.totalItems;

						//инициализация полей реестра
						initDisplayFilters();

						//инициализация сортировки
						const defOrder = $scope.data.registry.defaultOrder;
						if (orderField) {
							const orderFieldInDisplayFields = _.findWhere($scope.data.displayFields, { id: orderField.id });
							if (!orderFieldInDisplayFields) {
								_.each($scope.data.displayFields, (f) => f.sortOrder = null);
								orderField = null;
							}
						}
						if (!orderField && defOrder) {
							orderField = _.findWhere($scope.data.registry.fields, { id: defOrder.fieldId });
							if (orderField) {
								orderField.sortOrder = defOrder.ascending ? "asc" : "desc";
							}
						}

							

						//установка номеров строк
						_.each($scope.data.registryData.rows, (row, ind) => row.rownum = (($scope.paging.page - 1) * $scope.paging.pageSize) + ind + 1);

					} catch (ex) {
						errorHandle("Ошибка обработки данных: " + ex.message);
						return;
					}
					unsetLoadingState();
					$scope.state.emptyData = !response.data.rows.length;
				},
				(response) => {
					if (response && response.status === 401) {
						$.show.message(language.Generic.Common.kTimeOutOccured4Ajax)
							.then(
								() =>
								window.location.pathname = "/");
					} else {
						errorHandle("Ошибка загрузки данных " + (response && response.data ? response.data.message + (response.data.details ? " " + response.data.details : "") : ""));
					}
					
				});

		}

		$scope.clearLoad = () => {
			$scope.paging.page = 1;
			if ($scope.data.search.fieldId 
					&& $scope.data.search 
					&& $scope.data.search.fields 
					&& $scope.data.search.fields.length 
					&& !_.find($scope.data.search.fields, 
					(item) => item.id === $scope.data.search.fieldId)) {
				$scope.data.search.fieldId = $scope.data.search.fields[0].id;
				$scope.data.search.text = null;
			};
			$scope.load();
		}

		$scope.print = () => {
			alert("Печать пока не реализована");
		}

		const getDefaultExportFields = () => {
			let exportFields = $scope.data.displayFields;

			if (exportFields) {
				exportFields = exportFields.filter((field) => { return field.default; });
			}

			return exportFields;
		}

		//экспорт данных
		$scope.export = () => {
			if (!$scope.data.displayFields) {
				initDisplayFilters();

				$scope.data.displayFields = getDefaultExportFields();
			}

			let data = {
				filterContext: {
					selectedData: $scope.filterInfo.filterPanel.getCtxValues()
				},
				fields: _.pluck($scope.data.displayFields, "id"),
				search: $scope.data.search

				//экспорт всех данных
				//page: $scope.paging.page,
				//pageSize: $scope.paging.pageSize
			};

			let orderField = _.find($scope.data.displayFields, (f) => f.sortOrder);
			if (orderField) {
				data.order = {
					fieldId: orderField.id,
					ascending: orderField.sortOrder === "asc"
				}
			}
			$scope.state.exporting = true;
			const wait = $dialogs.wait("Операция выполняется");
			$http.post($scope.registry.url, data, {params: {"export": true} })
				.then((response) => {
						let fileId = response.data;
						wait.close();

						const isValidTempFileId = /^[0-9a-f]{24}$/i.test(fileId);
						if (!isValidTempFileId) {
							$alerts.error("Ошибка экспорта данных.", "Неизвестный ответ");
							return;
							
						}
						
						downloadFile(`/webapi/files/${fileId}`);
						$scope.state.exporting = false;
					},
					(response) => {
						$scope.state.exporting = false;
						$alerts.error("Ошибка экспорта данных.", response.data && response.data.message);
						wait.close();
					});
		};

		$scope.btnExport = {
			title: language.Generic.Common.kBtnExcel,
			action: $scope.export,
			hide: false,
			icon: "glyphicon glyphicon-export"
		};

		//выполнение команды реестра
		$scope.execCmd = (cmd) => {
			const confirms = [];
			if (cmd.confirm) {
				confirms.push($.show.getConfirmation(cmd.confirm));
			}

			extDeferred.when(confirms).then(() => {

				const wait = $dialogs.wait("Операция выполняется");
				const data = {
					itemId: _.pluck($scope.selection.selected, "id")
				};

				$http.post(`${$scope.registry.url}/command/${cmd.id}`, null, { params: data }).then(
					(response) => {
						wait.close();
						const result = response.data;
						if (result.success) {
							$.show.message(result.message);
							$scope.load();
						} else {
							$.show.error(result.message);
							if(result.needReload){
								$scope.load();	
							}
						}
					},
					(response) => {
						$.show.error(response.data && response.data.message, "Ошибка выполнения команды");
						wait.close();
					});

			});


		};

		//настройки
		$scope.settings = () => {
			const chooseFields = initAvailableFields();
			const oneCheckedOnly = (checked) => {
				return checked && _.countBy(chooseFields, (field) => field.selected ? 'checked' : 'notChecked').checked === 1;
			}
			_.each(chooseFields,
				(f) => {
					f.selected = _.findWhere($scope.data.fields, { id: f.id }) ? true : false;
					f.oneCheckedOnly = (checked) => { return oneCheckedOnly(checked) };
				}
			);

			var modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/global/templates/registrySettings.html",
				controller: 'RegistrySettingsCtrl',
				title: 'Настройки',
				resolve: {
					fields: () => chooseFields
				}
			});

			modalInstance.result.then((fields) => {
				let fieldIds = _.chain($scope.data.registry.fields)
									.pluck("id")
									.difference(_.pluck(fields, "id"))
									.intersection(_.pluck($scope.data.fields, "id"))
									.union(_.pluck(_.where(fields, {selected: true}), "id"))
									.value();
				$scope.data.fields = _.filter($scope.data.registry.fields, (item) => _.some(fieldIds, (id) => item.id === id));
				$scope.data.displayFields = _.filter($scope.data.displayFields, (item) => _.some(fieldIds, (id) => item.id === id));
				_.each(_.reject($scope.data.registry.fields, (item) => _.some(fieldIds, (id) => item.id === id)), (field) => field.sortOrder = null);
				$scope.load();
			});
		};
	})
	.controller("SetRegistryFieldSearchCtrl", ($scope, $uibModalInstance, search, field) => {
		$.extend($scope, { search: search, field: field });

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		};

		$scope.set = () => {
			$uibModalInstance.close($scope.search);
		};

	})
	.controller("RegistrySettingsCtrl", ($scope, $uibModalInstance, fields) => {
		$scope.fields = fields;

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		};

		$scope.set = () => {
			$uibModalInstance.close($scope.fields);
		};

	});



