"use strict";

import * as Rights from "approot/global/references/rights.js";
import * as TabItems from "approot/global/references/tabItems.js";

angular
	.module("irtech.netcity.school.users")
	.controller("StaffListCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider, pageContext, navigationService) => {

		pageContext.title = language.Generic.FilterUsers.kStaffList;
		pageContext.tabItem = TabItems.tbStaff;
		pageContext.parent = null;

		let hasRightsToGenerateNewPasswords = appContext.hasRights([Rights.arUsersEditAccountStaff, Rights.arUsersEditStaff]);
		$scope.canGenerateNewPass = hasRightsToGenerateNewPasswords;

		$scope.isLimitAccess = appContext.hasAnyRight([Rights.arShortInfoStaff]);

		$scope.editUser = (user) => {
			navigationService.navigateTo("/angular/school/userinfo/staff/" + user.id);
		}

		$scope.exportMoodle = () => {
			if ($scope.canExport()) {
				var exportParams = {
					filterContext: {
						selectedData: $scope.filterInfo.filterPanel.getCtxValues()
					},
					search: $scope.data.search.text
				};

				downloadFile("/webapi/users/staff/export/moodle", { data: exportParams, method: "post" });
			}
		}

		const btnExportMoodle = {
			title: language.Generic.Common.kExport_Moodle,
			action: $scope.exportMoodle
		};

		const mapOldFilterValues = () => {

			const fpVals = $scope.filterInfo.filterPanel.getValues();
			const abcFilter = fpVals.AbcFilter;

			//т.к. старая логика на publicusers_inc.asp странице работает так: если первая буква фильтра это " " - то считаем что это латин.  поэтому заменяю латин. на " " ниже
			let firstLetter = $("select[name=AbcFilter_start]").val();
			if (firstLetter == language.Generic.FilterUsers.kLatin_) {
				firstLetter = " ";
			}

			return {
				FL: firstLetter,
				LL: $("select[name=AbcFilter_end]").val(),
				GN: fpVals.GenderFilter,
				cp: $scope.paging.page - 1,
				PageSize: $scope.paging.pageSize,
				FilterType: $scope.data.search.text ? 2 : 1,
				SRCH_TEXT: $scope.data.search.text,
				fa: 1,
				WS: fpVals["work-status"]
			}
		}

		$scope.exportExt = () => {
			if ($scope.canExport()) {
				// расширенный экспорт при флажке FullAccessEditing = 1
				postTo({ path: "/asp/SetupSchool/ExportStaff.asp", params: mapOldFilterValues() });
			}
		}

		$scope.importStaffEasy = () => {
			postTo({ path: "/asp/SetupSchool/importStaff_Easy.asp" });
		}


		$scope.importStaffEasy2 = () => {
			$location.path("/staffImport");
		}

		$scope.import = () => {
			var separator = '<div class="form-group"><div class="input-group"><div class="input-group-addon">Разделитель</div><input type="text" class="form-control" name="Separator" size="1" value=";" maxlength="1"></div></div>';
			var help = `<a href="/asp/SetupSchool/import.asp?RT=1" target="_helpImport">${language.Generic.SetupSchoolUI.kHowToUseImport}</a>`;

			$.show.fileDialog({
				title: language.Generic.Import.kStaffImport,
				fileExts: [".csv"],
				invalidFileExtMsg: language.Generic.Curriculum.kInvalidImportFileCsv,
				additionalContent: separator + help,
				url: "/asp/ajax/UploadImportFile.asp",
				isAjax: true,
				handlerAjaxSuccess: () => {
					var params = {
						importUrl: "/asp/SetupSchool/importStaff.asp",
						customComplete: (dialog) => {
							dialog.setTitle(language.Generic.Import.kStaffImport);
						},
						beginImport: () => {
							heavyAction(() => {
								var message = language.Generic.Import.kImportStaffProcessPleaseWait + ". " + language.Generic.Movement.kPleaseWait;
								$.show.processing(message);
								postTo("/asp/SetupSchool/importStaffSave.asp");
							});
						}
					};

					window.importHandler(params);
				},
				customCheck: (form) => {
					if (!$('input[name="Separator"]').val()) {
						alert(`${language.Generic.SetupSchoolUI.kMsgInpuDelimiter} (${language.Generic.SetupSchoolUI.kMsgExample}, ',' ${language.Generic.SetupSchoolUI.kMsgOr} ';')`);
						return false;
					}

					return true;
				},
				onShownDlg: () => {
					$('input[name="Separator"]').val(";");
				}
			});
		}

		const addBtn = {
			title: language.Generic.Buttons.kAdd,
			icon: "glyphicon glyphicon-plus-sign",
			action: () => {
				postTo({ path: "/asp/SetupSchool/StaffQAdd.asp" });
			}
		};

		const importBtnGroup = {
			title: language.Generic.Buttons.kImportExportBtn,
			icon: "glyphicon glyphicon-import",
			buttons: [
				{ title: language.Generic.Common.kExportExcelExt, action: $scope.exportExt },
				{ title: language.Generic.Buttons.kImport, action: $scope.import },
				// { title: language.Generic.Buttons.kImport + " из другой ОО", action: $scope.importStaffEasy }, //СТАРЫЙ ВАРИАНТ
				{ title: language.Generic.Buttons.kImport + " из другой ОО", action: $scope.importStaffEasy2 },
			]
		};

		$scope.registry = {
			url: "/webapi/users/staff/registry",
			filtersUrl: "/webapi/users/staff/registry/filter",
			fieldDecorators: {
				"fio": { type: "link", action: $scope.editUser }
			},
			buttons: [addBtn],
			linkButtons: [btnExportMoodle],
			buttonGroups: [importBtnGroup]
		};

		settingsProvider.AppFlags.PersonData().then((personData) => {
			if (!personData) {
				$scope.registry.fieldDecorators["fio"] = null;
				addBtn.hide = true;
				btnExportMoodle.hide = true;
				importBtnGroup.hide = true;
				$scope.btnExport.hide = true;
			}
			else {
				if (appContext.readOnly || !appContext.hasAnyRight([Rights.arUsersEditStaff])) {
					addBtn.hide = true;
					btnExportMoodle.hide = true;
					importBtnGroup.hide = true;
				}
			}
		});

		$controller("UserListCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider });

	});


