"use strict";

import * as FuncTypes from "approot/global/references/funcTypes.js";
import * as exporter from "./exporter.js"
import * as Rights from "approot/global/references/rights.js";
import * as TabItems from "approot/global/references/tabItems.js";

angular
	.module("irtech.netcity.school.users")
	.controller("StudentListCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider, pageContext, navigationService) => {

		deferredResLoader.loadJsScript("/js/ImportUpdatePersons.js");

		let hasRightsToGenerateNewPasswords = appContext.hasRights([Rights.arUsersEditStudents, Rights.arUsersEditAccountStudentsParents]);
		$scope.canGenerateNewPass = appContext.funcType != FuncTypes.addSchool && appContext.funcType != FuncTypes.preSchool && hasRightsToGenerateNewPasswords;

		pageContext.title = language.FilterUsers.kStudentList;
		pageContext.tabItem = TabItems.tbStudents;
		pageContext.parent = null;

		$scope.isLimitAccess = !appContext.hasAnyRight([Rights.arUsersEditStudents]);

		$scope.editUser = (user) => {
			navigationService.navigateTo("/angular/school/userinfo/students/" + user.id);
		};

		$scope.batchExportStudents = () => {
			if ($scope.canExport()) {
				var filterContext = { selectedData: $scope.filterInfo.filterPanel.getCtxValues() };
				var searchText = $scope.data.search.text;

				exporter.exportStudents("/webapi/users/students/export", filterContext, searchText);
			}
		}

		$scope.batchUpdateStudents = () => {
			window.importUpdatePerson.execute();
		}

		$scope.exportMoodle = () => {
			if ($scope.canExport()) {
				var exportParams = {
					filterContext: {
						selectedData: $scope.filterInfo.filterPanel.getCtxValues()
					},
					search: $scope.data.search.text
				};

				downloadFile("/webapi/users/students/export/moodle", { data: exportParams, method: "post" });
			}
		}

		const batchUpdateBtnGroup = {
			title: "Пакетное обновление",
			icon: "glyphicon glyphicon-import",
			buttons: [
				{ title: "1. Выгрузка данных", action: $scope.batchExportStudents },
				{ title: "2. Обновление данных", action: $scope.batchUpdateStudents, hide: $scope.isLimitAccess }
			]
		};

		$scope.registry = {
			url: "/webapi/users/students/registry",
			filtersUrl: "/webapi/users/students/registry/filter",
			fieldDecorators: {
				"nickname": { type: "link", action: $scope.editUser }
			},
			buttons: [],
			linkButtons: [],
			buttonGroups: []
		};

		const btnAdd = {
			title: language.Generic.Buttons.kAdd,
			icon: "glyphicon glyphicon-plus-sign",
			action: () => {
				//todo: кажется, пока не было мержа, поэтому вернул пока прежний вариант
				// postTo({ path: "/angular/school/movement/movedoc/?docType=Enroll" });
				postTo({ path: "/asp/SetupSchool/Movement/MoveBookEdit.asp?DOCTYPE=2", params: { BACK: "/angular/school/users/students/" }});
			}
		};

		// Расширенный экспорт в Excel
		const btnExportExt = {
			title: language.Generic.Buttons.kExport,
			icon: "glyphicon glyphicon-import",
			action: $scope.batchExportStudents
		};

		const btnExportMoodle = {
			title: language.Generic.Common.kExport_Moodle,
			action: $scope.exportMoodle
		};

		if (!appContext.readOnly && appContext.funcType !== FuncTypes.addSchool) {
			$scope.registry.linkButtons.push(btnExportMoodle);
		}

		if (!appContext.readOnly && appContext.hasAnyRight([Rights.arMoveBookEdit])) {
			$scope.registry.buttons.push(btnAdd);
			if (appContext.funcType !== FuncTypes.addSchool) {
				$scope.registry.buttonGroups.push(batchUpdateBtnGroup);
			}
		}

		if (appContext.isEmForSchool && (appContext.readOnly || !appContext.hasAnyRight([Rights.arMoveBookEdit]) || appContext.funcType === FuncTypes.addSchool)) {
			$scope.registry.buttons.push(btnExportExt);
		}

		settingsProvider.AppFlags.PersonData().then((personData) => {
			if (!personData) {
				$scope.registry.fieldDecorators["nickname"] = null;
				btnAdd.hide = true;
				batchUpdateBtnGroup.hide = true;
				btnExportMoodle.hide = true;
				$scope.btnExport.hide = true;
			}
		});

		$controller("UserListCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider });
	});


